const items = $input.all();
const item = items[0] || {};
const body = item.json || {};

let text = '';
try {
  text = (body.candidates?.[0]?.content?.parts ?? [])
    .filter(p => !p.thought)
    .map(p => p.text || '')
    .join('\n')
    .trim();
} catch (e) {
  text = '';
}

const companyName = $('Config').first().json.company_name || 'Unknown Company';

if (!text) {
  return [{ json: { status: 'gemini_error', message: 'Empty response from Gemini.' } }];
}

if (text.toLowerCase().includes('no pnl found')) {
  return [{ json: { status: 'no_pnl' } }];
}

let cleaned = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/,'').trim();

if (!cleaned.startsWith('{')) {
  const m = cleaned.match(/\{[\s\S]*\}/);
  if (m) cleaned = m[0];
}

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  return [{ json: { status: 'invalid_json', raw: text.slice(0, 500) } }];
}

if (!parsed.company_name || parsed.company_name === 'Unknown Company') {
  parsed.company_name = companyName;
}

return [{ json: { status: 'ok', data: parsed } }];

// Recalculates EBITDA margin, PAT margin, and Profit Before Tax from the AI
// numbers. If any recalculated value differs from the AI value by more than
// 0.05, sets a warning string that Build HTML Table / Split Recipients will
// append to the WhatsApp caption.
//
// CRITICAL: This node does NOT change the AI JSON. It only adds a sibling
// field `number_check_warning` that downstream nodes read.

const payload = $input.all()[0].json || {};
const data = payload.data || payload;

const rowKeys = Object.keys(data)
  .filter(k => /^row\d+$/.test(k))
  .sort((a, b) => parseInt(a.slice(3), 10) - parseInt(b.slice(3), 10));

function num(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === 'number') return v;
  const s = String(v).trim().replace(/%$/, '').replace(/,/g, '');
  if (s === '' || s === '-' || s.toLowerCase() === 'na' || s.toLowerCase() === 'n/a') return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

function findRow(needles, excludeMargin = false) {
  const nl = needles.map(s => s.toLowerCase());
  for (const k of rowKeys) {
    const row = data[k] || [];
    const label = String(row[0] || '').toLowerCase();
    if (excludeMargin && label.includes('margin')) continue;
    if (nl.some(n => label.includes(n))) return row;
  }
  return null;
}

const header = data.row1 || [];
const isExtended = (header.length >= 6) || (data.quarter_type || '').toLowerCase() === 'extended';
const dataCols = isExtended ? [1, 2, 3, 4, 5] : [1, 2, 3];

const revenueRow       = findRow(['revenue']);
const ebitdaRow        = findRow(['ebitda'], true);
const ebitdaMarginRow  = findRow(['ebitda margin']);
const patRow           = findRow(['pat'], true);
const patMarginRow     = findRow(['pat margin']);
const depreciationRow  = findRow(['depreciation']);
const financeCostRow   = findRow(['finance cost']);
const otherIncomeRow   = rowKeys.map(k => data[k] || []).find(r => /^other income/i.test(String(r[0] || '').trim())) || null;
const pbtRow           = findRow(['profit before tax', 'profit/loss before tax'], true);
const allRows = rowKeys.map(k => data[k] || []);
const exceptionalRow = allRows.find(r => /^exceptional/i.test(String(r[0] || '').trim())) || null;
const jvRow = allRows.find(r => /share of/i.test(String(r[0] || ''))) || null;

const warnings = [];
const TOLERANCE = 0.05;

for (const col of dataCols) {
  const rev    = revenueRow      ? num(revenueRow[col])      : null;
  const ebitda = ebitdaRow       ? num(ebitdaRow[col])       : null;
  const ebitdaM = ebitdaMarginRow ? num(ebitdaMarginRow[col]) : null;
  const pat    = patRow          ? num(patRow[col])          : null;
  const patM   = patMarginRow    ? num(patMarginRow[col])    : null;
  const dep    = depreciationRow ? num(depreciationRow[col]) : null;
  const fc     = financeCostRow ? num(financeCostRow[col])  : null;
  const oi     = otherIncomeRow ? num(otherIncomeRow[col])  : null;
  const pbt    = pbtRow          ? num(pbtRow[col])          : null;

  if (rev && rev !== 0 && ebitda !== null && ebitdaM !== null) {
    const calc = (ebitda / rev) * 100;
    if (Math.abs(calc - ebitdaM) > TOLERANCE) {
      warnings.push(`Column ${header[col] || col}: EBITDA margin AI=${ebitdaM.toFixed(2)}% vs calc=${calc.toFixed(2)}%`);
    }
  }

  if (rev && rev !== 0 && pat !== null && patM !== null) {
    const calc = (pat / rev) * 100;
    if (Math.abs(calc - patM) > TOLERANCE) {
      warnings.push(`Column ${header[col] || col}: PAT margin AI=${patM.toFixed(2)}% vs calc=${calc.toFixed(2)}%`);
    }
  }

  if (ebitda !== null && dep !== null && fc !== null && pbt !== null) {
    const exc = exceptionalRow ? (num(exceptionalRow[col]) || 0) : 0;
    const jv = jvRow ? (num(jvRow[col]) || 0) : 0;
    const base = ebitda - dep - fc + (oi || 0);
    const options = [base + exc + jv, base - exc - jv, base];
    const okPbt = options.some(v => Math.abs(v - pbt) <= TOLERANCE);
    if (!okPbt) {
      warnings.push(`Column ${header[col] || col}: PBT AI=${pbt.toFixed(2)} vs calc=${options[0].toFixed(2)}`);
    }
  }
}

const warningText = warnings.length === 0
  ? ''
  : 'Warning: some numbers may need a manual check.';

return [{
  json: {
    status: 'ok',
    data: data,
    number_check_warning: warningText,
    number_check_details: warnings
  }
}];

// Builds a styled HTML P&L table that visually mirrors the
// iValue Infosolutions Limited sample image.
const DARK_GREEN = '#1d6b3e';
const LIGHT_BLUE = '#cfe2f3';
const BORDER = '#7f7f7f';

const HIGHLIGHT_ROWS = new Set([
  'Gross Profit',
  'Gross Profit Margin',
  'EBITDA',
  'EBITDA Margin',
  'Profit before Exceptional Items, Other Income',
  'Profit Before Tax',
  'PAT',
  'PAT Margin',
]);

const NO_CHANGE_ROWS = new Set([
  'Gross Profit Margin',
  'EBITDA Margin',
  'PAT Margin',
  'EPS (Basic)',
]);

function num(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === 'number') return v;
  const s = String(v).trim().replace(/%$/, '').replace(/,/g, '');
  if (s === '' || s === '-' || s.toLowerCase() === 'na' || s.toLowerCase() === 'n/a') return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

function pct(cur, cmp) {
  const a = num(cur);
  const b = num(cmp);
  if (a === null || b === null || b === 0) return '';
  const v = ((a - b) / Math.abs(b)) * 100;
  const sign = v > 0 ? '+' : '';
  return sign + v.toFixed(2) + '%';
}

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const payload = $input.all()[0].json || {};
const data = payload.data || payload;
const companyName = data.company_name || 'Unknown Company';
const numberCheckWarning = payload.number_check_warning || '';
const quarterType = (data.quarter_type || 'standard').toLowerCase();

const rowKeys = Object.keys(data)
  .filter(k => /^row\d+$/.test(k))
  .sort((a, b) => parseInt(a.slice(3), 10) - parseInt(b.slice(3), 10));

const rows = rowKeys.map(k => data[k] || []);

const header = rows[0] || [];
const headerCols = header.length;
const isExtended = headerCols >= 6 || quarterType === 'extended';

let cols;
if (isExtended) {
  cols = [
    { label: header[0], kind: 'particulars' },
    { label: header[1], kind: 'data', dataIndex: 1 },
    { label: header[2], kind: 'data', dataIndex: 2 },
    { label: 'Change (in %)', kind: 'change', cur: 1, cmp: 2 },
    { label: header[3], kind: 'data', dataIndex: 3 },
    { label: 'Change (in %)', kind: 'change', cur: 1, cmp: 3 },
    { label: header[4], kind: 'data', dataIndex: 4 },
    { label: header[5], kind: 'data', dataIndex: 5 },
    { label: 'Change (in %)', kind: 'change', cur: 4, cmp: 5 },
  ];
} else {
  cols = [
    { label: header[0], kind: 'particulars' },
    { label: header[1], kind: 'data', dataIndex: 1 },
    { label: header[2], kind: 'data', dataIndex: 2 },
    { label: 'Change (in %)', kind: 'change', cur: 1, cmp: 2 },
    { label: header[3], kind: 'data', dataIndex: 3 },
    { label: 'Change (in %)', kind: 'change', cur: 1, cmp: 3 },
  ];
}

const trs = [];

{
  const tds = [];
  tds.push(`<th style="background:${LIGHT_BLUE};color:#000;border:1px solid ${BORDER};padding:4px 8px;font-weight:bold;text-align:left;">Rs in Cr</th>`);
  for (let i = 1; i < cols.length; i++) {
    const c = cols[i];
    const bg = c.kind === 'change' ? '#f3f3f3' : LIGHT_BLUE;
    tds.push(`<th style="background:${bg};color:#000;border:1px solid ${BORDER};padding:4px 8px;font-weight:bold;text-align:right;">${esc(c.label)}</th>`);
  }
  trs.push(`<tr>${tds.join('')}</tr>`);
}

for (let r = 1; r < rows.length; r++) {
  const row = rows[r] || [];
  const label = String(row[0] || '').trim();
  const highlight = HIGHLIGHT_ROWS.has(label);
  const noChange = NO_CHANGE_ROWS.has(label) || label.toLowerCase() === 'eps (basic)' || label.toLowerCase().startsWith('eps');

  const tds = [];
  const labelStyle = highlight
    ? `background:${DARK_GREEN};color:#fff;font-weight:bold;border:1px solid ${BORDER};padding:4px 8px;text-align:left;`
    : `background:#fff;color:#000;border:1px solid ${BORDER};padding:4px 8px;text-align:left;`;
  tds.push(`<td style="${labelStyle}">${esc(label)}</td>`);

  for (let i = 1; i < cols.length; i++) {
    const c = cols[i];
    let cellValue = '';
    let styleExtra = '';
    if (c.kind === 'data') {
      cellValue = esc(row[c.dataIndex] != null ? row[c.dataIndex] : '');
      styleExtra = highlight
        ? `background:${DARK_GREEN};color:#fff;font-weight:bold;`
        : `background:#fff;color:#000;`;
    } else if (c.kind === 'change') {
      if (noChange) {
        cellValue = '';
      } else {
        cellValue = pct(row[c.cur], row[c.cmp]);
      }
      styleExtra = `background:#fafafa;color:#444;font-style:italic;`;
    }
    tds.push(`<td style="${styleExtra}border:1px solid ${BORDER};padding:4px 8px;text-align:right;font-size:11px;">${cellValue}</td>`);
  }
  trs.push(`<tr>${tds.join('')}</tr>`);
}

const tableHtml = `
<table style="border-collapse:collapse;font-family:'Times New Roman',Times,serif;font-size:12px;width:100%;">
${trs.join('\n')}
</table>`;

const html = `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8" />
<title>${esc(companyName)} - Financial Results</title>
<style>
  body { margin:0; padding:0; background:#ffffff; font-family:'Times New Roman',Times,serif; }
  .wrap { width:780px; padding:0; }
  .header {
    background:${LIGHT_BLUE};
    color:#000;
    padding:8px 12px;
    display:flex;
    justify-content:space-between;
    align-items:center;
    font-weight:bold;
    border:1px solid ${BORDER};
    border-bottom:none;
    font-family:'Times New Roman',Times,serif;
  }
  .header .company { font-size:14px; }
  .header .brand { font-size:13px; letter-spacing:1px; }
  table { border-collapse:collapse; }
</style>
</head>
<body>
  <div class="wrap">
    <div class="header">
      <div class="company">${esc(companyName)}</div>
      <div class="brand">NIVESHAAY</div>
    </div>
    ${tableHtml}
  </div>
</body>
</html>`;

// ---- Plain-text version (used only if the image service is unavailable) ----
const dataCols = isExtended ? [1, 2, 3, 4, 5] : [1, 2, 3];
const wanted = [/^revenue/i, /^gross profit$/i, /^ebitda$/i, /^ebitda margin/i, /before tax/i, /^pat$/i, /^pat margin/i, /^eps/i];
const lines = [];
lines.push('*' + companyName + ' - Financial Results* (Rs Cr)');
lines.push('Period: ' + dataCols.map(i => header[i] || '').join(' | '));
for (let r = 1; r < rows.length; r++) {
  const row = rows[r] || [];
  const label = String(row[0] || '').trim();
  if (wanted.some(re => re.test(label))) {
    lines.push(label + ': ' + dataCols.map(i => (row[i] !== undefined && row[i] !== null && row[i] !== '') ? row[i] : '-').join(' | '));
  }
}
let textTable = lines.join('\n');
if (textTable.length > 1400) textTable = textTable.slice(0, 1400);

// ---- Short summary parts (used by Twilio template mode) ----
const firstVal = (re) => {
  for (let r = 1; r < rows.length; r++) {
    const row = rows[r] || [];
    if (re.test(String(row[0] || '').trim())) {
      return (row[1] !== undefined && row[1] !== null && row[1] !== '') ? String(row[1]) : '-';
    }
  }
  return '-';
};
const var_parts = [
  companyName + ' ' + (header[1] || ''),
  'Revenue ' + firstVal(/^revenue/i) + ' | EBITDA ' + firstVal(/^ebitda$/i) + ' | PAT ' + firstVal(/^pat$/i) + ' | EPS ' + firstVal(/^eps/i) + ' (Rs Cr)',
  'EBITDA margin ' + firstVal(/^ebitda margin/i) + ' | PAT margin ' + firstVal(/^pat margin/i)
];

// ---- hcti.io login header, built from the Config node (spaces are removed) ----
const cfgNode = $('Config').first().json;
const strip = (v) => String(v === undefined || v === null ? '' : v).replace(/\s+/g, '');
const hcti_auth = 'Basic ' + Buffer.from(strip(cfgNode.hcti_api_id) + ':' + strip(cfgNode.hcti_api_key)).toString('base64');

return [{ json: { company_name: companyName, html, text_table: textTable, var_parts, hcti_auth, number_check_warning: numberCheckWarning } }];

// Builds one WhatsApp request per recipient.
// delivery_provider = meta | evolution | twilio   (set in the Config node)
const config = $('Config').first().json;
const strip = (v) => String(v === undefined || v === null ? '' : v).replace(/\s+/g, '');
const digits = (v) => String(v === undefined || v === null ? '' : v).replace(/\D+/g, '');
const needs = (name) => {
  const v = strip(config[name]);
  if (!v || /^PASTE_/i.test(v)) {
    throw new Error('Please fill "' + name + '" in the Config node.');
  }
  return v;
};

const companyName = config.company_name || 'Company';
const built = $('Build HTML Table').first().json;
const warning = built.number_check_warning || '';
const text = built.text_table || (companyName + ' - Financial Results');
const hcti = $('HTML to Image').first().json || {};
const hctiUrl = (typeof hcti.url === 'string') ? hcti.url : '';
const mediaUrl = hctiUrl ? (/\.(png|jpg|jpeg|webp)$/i.test(hctiUrl) ? hctiUrl : hctiUrl + '.png') : '';

const caption = (companyName + ' - Financial Results' + (warning ? '\n' + warning : '')).slice(0, 1000);
const textBody = (text + (warning ? '\n' + warning : '') + '\n(Image could not be generated, so this result was sent as text.)').slice(0, 1550);

const provider = String(config.delivery_provider || 'meta').trim().toLowerCase();
const recipients = String(config.recipient_numbers || '').split(',').map(digits).filter(s => s.length >= 8);
if (recipients.length === 0) {
  throw new Error('Please fill "recipient_numbers" in the Config node (digits with country code, for example 919876543210).');
}

const items = [];
for (const r of recipients) {
  let req;
  if (provider === 'meta') {
    const ver = strip(config.meta_api_version) || 'v23.0';
    const url = 'https://graph.facebook.com/' + ver + '/' + needs('meta_phone_number_id') + '/messages';
    const payload = mediaUrl
      ? { messaging_product: 'whatsapp', recipient_type: 'individual', to: r, type: 'image', image: { link: mediaUrl, caption: caption } }
      : { messaging_product: 'whatsapp', recipient_type: 'individual', to: r, type: 'text', text: { preview_url: false, body: textBody } };
    req = { url, authorization: 'Bearer ' + needs('meta_access_token'), apikey: 'none', content_type: 'application/json', body: JSON.stringify(payload) };
  } else if (provider === 'evolution') {
    const base = needs('evolution_url').replace(/\/+$/, '');
    const inst = needs('evolution_instance');
    const payload = mediaUrl
      ? { number: r, mediatype: 'image', mimetype: 'image/png', caption: caption, media: mediaUrl, fileName: 'pnl.png' }
      : { number: r, text: textBody };
    const path = mediaUrl ? '/message/sendMedia/' : '/message/sendText/';
    req = { url: base + path + inst, authorization: 'none', apikey: needs('evolution_api_key'), content_type: 'application/json', body: JSON.stringify(payload) };
  } else if (provider === 'twilio') {
    const sid = needs('twilio_account_sid');
    const token = needs('twilio_auth_token');
    const from = digits(needs('twilio_from'));
    const enc = encodeURIComponent;
    const form = 'From=' + enc('whatsapp:+' + from) + '&To=' + enc('whatsapp:+' + r)
      + (mediaUrl ? '&Body=' + enc(caption) + '&MediaUrl=' + enc(mediaUrl) : '&Body=' + enc(textBody));
    req = { url: 'https://api.twilio.com/2010-04-01/Accounts/' + sid + '/Messages.json',
            authorization: 'Basic ' + Buffer.from(sid + ':' + token).toString('base64'), apikey: 'none',
            content_type: 'application/x-www-form-urlencoded', body: form };
  } else {
    throw new Error('delivery_provider must be meta, evolution or twilio (now: ' + provider + ').');
  }
  items.push({ json: {
    to: r, provider: provider, mode: mediaUrl ? 'image' : 'text',
    req_url: req.url, req_authorization: req.authorization, req_apikey: req.apikey,
    req_content_type: req.content_type, req_body: req.body
  } });
}
return items;

const items = $input.all();
const ok = (j) => !!(j.sid || (j.key && j.key.id) || (Array.isArray(j.messages) && j.messages[0] && j.messages[0].id));
const reason = (j) => {
  if (j.error && typeof j.error === 'object' && j.error.message) {
    return (j.error.code ? 'Error ' + j.error.code + ': ' : '') + j.error.message;
  }
  if (j.response && j.response.message) {
    return (j.status ? 'Error ' + j.status + ': ' : '') + (Array.isArray(j.response.message) ? j.response.message.join(' ') : String(j.response.message));
  }
  if (j.message) {
    return (j.code ? 'Error ' + j.code + ': ' : '') + String(j.message);
  }
  if (typeof j.error === 'string') return j.error;
  return JSON.stringify(j).slice(0, 300);
};
const failed = items.filter(i => !ok(i.json));
return [{ json: {
  total: items.length,
  succeeded: items.length - failed.length,
  failed: failed.length,
  all_succeeded: failed.length === 0 && items.length > 0,
  first_error: failed.length ? reason(failed[0].json) : ''
} }];
